55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
68	const BLOCK_SIZE = 3;
69	const BLOCK_PREMIUM = 60;
70	
71	/**
72	 * A building block is exactly BLOCK_SIZE alike components — four runes are
73	 * priced per unit, not as a block plus a spare (prompt: "4 runes -> 100 G").
74	 */
75	function componentBase(type: string, count: number): number {
76	  if (count === BLOCK_SIZE) return BLOCK_PREMIUM;
77	  return count * BASE_PREMIUMS[type];
78	}
79	
80	const CURSE_SURCHARGE = 0.5;
81	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	
84	function policyBasePremium(items: Item[]): number {
85	  const componentCounts = new Map<string, number>();
86	  let base = 0;
87	
88	  for (const item of items) {
89	    if (COMPONENT_TYPES.has(item.type)) {
90	      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
91	    } else {
92	      base += BASE_PREMIUMS[item.type];
93	    }
94	  }
95	
96	  for (const [type, count] of componentCounts) {
97	    base += componentBase(type, count);
98	  }
99	
100	  return base;
101	}
102	
103	/**
104	 * Surcharges that attach to a single item, each a fraction of that item's own
105	 * base premium rather than of the policy total.
106	 */
107	function itemSurcharges(items: Item[]): number {
108	  return items.reduce((sum, item) => {
109	    if (COMPONENT_TYPES.has(item.type)) return sum;
110	    const itemBase = BASE_PREMIUMS[item.type];
111	    const curse = item.cursed ? itemBase * CURSE_SURCHARGE : 0;
112	    const enchanted =
113	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
114	        ? itemBase * HIGH_ENCHANTMENT_SURCHARGE
115	        : 0;
116	    return sum + curse + enchanted;
117	  }, 0);
118	}
119	
120	const LOYALTY_DISCOUNT = 0.2;
121	const LOYALTY_THRESHOLD_YEARS = 2;
122	const FOLLOW_UP_DISCOUNT = 0.15;
123	
124	/**
125	 * Discounts and surcharges that attach to the policy as a whole, each a
126	 * fraction of the summed item base premiums.
127	 */
128	function policyAdjustments(
129	  policyBase: number,
130	  customer: Customer,
131	  isFollowUpContract: boolean,
132	): number {
133	  const loyalty =
134	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
135	      ? -policyBase * LOYALTY_DISCOUNT
136	      : 0;
137	  const followUp = isFollowUpContract ? -policyBase * FOLLOW_UP_DISCOUNT : 0;
138	  return loyalty + followUp + policyBase * FIRST_INSURANCE_SURCHARGE;
139	}
140	
141	function quotePremium(
142	  items: Item[],
143	  customer: Customer,
144	  isFollowUpContract: boolean,
145	): number {
146	  const policyBase = policyBasePremium(items);
147	  const total =
148	    policyBase +
149	    itemSurcharges(items) +
150	    policyAdjustments(policyBase, customer, isFollowUpContract);
151	  return Math.ceil(total + PROCESSING_FEE);
152	}
153	
154	const INSURANCE_VALUES: Record<string, number> = {
155	  sword: 1000,
156	  amulet: 600,
157	  staff: 800,
158	  potion: 400,
159	  rune: 250,
160	  moonstone: 250,
161	};
162	
163	const DEDUCTIBLE = 100;
164	const CAP_MULTIPLE = 2;
165	
166	interface Policy {
167	  items: Item[];
168	  remainingCap: number;
169	}
170	
171	function openPolicy(items: Item[]): Policy {
172	  const insuranceSum = items.reduce(
173	    (sum, item) => sum + INSURANCE_VALUES[item.type],
174	    0,
175	  );
176	  return { items, remainingCap: insuranceSum * CAP_MULTIPLE };
177	}
178	
179	const HALVED_ENCHANTMENT_THRESHOLD = 8;
180	const HALVED_REIMBURSEMENT = 0.5;
181	
182	/**
183	 * Reimbursement for one damaged item, before the policy cap is applied.
184	 * The high-enchantment clause takes precedence over full dragon-material
185	 * reimbursement when both would apply.
186	 */
187	function reimbursement(item: Item, amount: number): number {
188	  const covered =
189	    (item.enchantment ?? 0) >= HALVED_ENCHANTMENT_THRESHOLD
190	      ? amount * HALVED_REIMBURSEMENT
191	      : amount;
192	  return Math.max(0, covered - DEDUCTIBLE);
193	}
194	
195	/**
196	 * Pairs each damage with a distinct insured item, so a policy covering one
197	 * sword cannot absorb two sword damages.
198	 */
199	function matchDamagesToItems(policy: Policy, damages: Damage[]): Item[] {
200	  const unclaimed = [...policy.items];
201	
202	  return damages.map((damage) => {
203	    if (damage.amount < 0) {
204	      throw new ScenarioError(`negative damage amount: ${damage.amount}`);
205	    }
206	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
207	    if (index === -1) {
208	      throw new ScenarioError(`policy does not cover a damaged ${damage.itemType}`);
209	    }
210	    return unclaimed.splice(index, 1)[0];
211	  });
212	}
213	
214	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
215	  const damagedItems = matchDamagesToItems(policy, incident.damages);
216	  const desired = incident.damages.reduce(
217	    (sum, damage, i) => sum + reimbursement(damagedItems[i], damage.amount),
218	    0,
219	  );
220	  // Rounded in the MHPCO's favour, then the cap draws down by what was paid.
221	  const payout = Math.floor(Math.min(desired, policy.remainingCap));
222	  policy.remainingCap -= payout;
223	  return { payout, remainingCap: policy.remainingCap };
224	}
225	
226	/** Rejects a whole scenario; the CLI turns this into a non-zero exit. */
227	export class ScenarioError extends Error {}
228	
229	function assertKnownItems(items: Item[]): void {
230	  for (const item of items) {
231	    if (!(item.type in BASE_PREMIUMS)) {
232	      throw new ScenarioError(`unknown item type: ${item.type}`);
233	    }
234	  }
235	}
236	
237	export function runScenario(scenario: Scenario): ScenarioOutput {
238	  const policies = new Map<number, Policy>();
239	  let quotesSoFar = 0;
240	
241	  const results = scenario.steps.map((step, index): StepResult => {
242	    if (step.op === "claim") {
243	      const policy = policies.get(step.policy)!;
244	      return settleClaim(policy, step.incident);
245	    }
246	
247	    assertKnownItems(step.items);
248	
249	    const premium = quotePremium(step.items, scenario.customer, quotesSoFar > 0);
250	    quotesSoFar += 1;
251	    policies.set(index, openPolicy(step.items));
252	    return { premium };
253	  });
254	
255	  return { results };
256	}
