4	async function readStdin(): Promise<string> {
5	  const chunks: Buffer[] = [];
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk as Buffer);
8	  }
9	  return Buffer.concat(chunks).toString("utf8");
10	}
11	
12	async function main(): Promise<void> {
13	  const input = await readStdin();
14	  const scenario = JSON.parse(input) as Scenario;
15	  process.stdout.write(JSON.stringify(runScenario(scenario)) + "\n");
16	}
17	
18	main().catch((error: unknown) => {
19	  process.stderr.write(`${error instanceof Error ? error.message : error}\n`);
20	  process.exitCode = 1;
21	});
