177	  damages: Array<{ itemType: string; amount: number }>,
178	) {
179	  const { results } = runScenario({
180	    customer: { yearsWithMHPCO: 0 },
181	    steps: [
182	      { op: "quote", items },
183	      { op: "claim", policy: 0, incident: { cause: "dragon attack", damages } },
184	    ],
185	  });
186	  return results[1];
